// Generates every Tasklist icon (pure Node, no dependencies): red rounded square with a white check mark.
//   apps/desktop/electron/icon.png           256  desktop / installer icon
//   packages/core/icons/icon-192.png, -512   PWA "any" icons (transparent rounded corners)
//   packages/core/icons/maskable-512.png     PWA maskable icon (full bleed, mark inside the safe zone)
//   packages/core/icons/apple-touch-icon.png 180  iOS home screen
//   apps/website/assets/icon-*.png           landing site logo and favicon
// Android launcher icons are generated by apps/mobile/android-assets.js using draw() from this file.
// Run: npm run icons
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const C = [209, 73, 60];

function distToSeg(x, y, x1, y1, x2, y2) {
  const dx = x2 - x1, dy = y2 - y1;
  const t = Math.max(0, Math.min(1, ((x - x1) * dx + (y - y1) * dy) / (dx * dx + dy * dy)));
  return Math.hypot(x - (x1 + t * dx), y - (y1 + t * dy));
}

// Coverage-based anti-aliasing: sample each pixel on a 4x4 grid.
function draw(S, { bleed = false, markScale = 1, markOnly = false, radius = 0.22 } = {}) {
  const px = Buffer.alloc(S * S * 4);
  const R = bleed ? 0 : S * radius;
  const k = S / 256;
  const m = (v) => S / 2 + (v - 128) * k * markScale; // check mark designed on a 256 grid
  const w = 15 * k * markScale;
  const inside = (x, y) => {
    if (bleed) return true;
    const cx = Math.min(Math.max(x, R), S - R), cy = Math.min(Math.max(y, R), S - R);
    return (x - cx) ** 2 + (y - cy) ** 2 <= R * R;
  };
  const N = 4;
  for (let y = 0; y < S; y++) {
    for (let x = 0; x < S; x++) {
      let bg = 0, check = 0;
      for (let sy = 0; sy < N; sy++) for (let sx = 0; sx < N; sx++) {
        const X = x + (sx + .5) / N, Y = y + (sy + .5) / N;
        if (!markOnly && !inside(X, Y)) continue;
        bg++;
        if (Math.min(distToSeg(X, Y, m(70), m(132), m(112), m(174)), distToSeg(X, Y, m(112), m(174), m(190), m(88))) <= w) check++;
      }
      const i = (y * S + x) * 4, a = markOnly ? check / (N * N) : bg / (N * N), c = markOnly ? 1 : bg ? check / bg : 0;
      px[i] = Math.round(C[0] + (255 - C[0]) * c);
      px[i + 1] = Math.round(C[1] + (255 - C[1]) * c);
      px[i + 2] = Math.round(C[2] + (255 - C[2]) * c);
      px[i + 3] = Math.round(255 * a);
    }
  }
  return encode(S, px);
}

const crcTable = Array.from({ length: 256 }, (_, n) => { let c = n; for (let j = 0; j < 8; j++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; return c >>> 0; });
const crc = (buf) => { let c = 0xffffffff; for (const b of buf) c = crcTable[(c ^ b) & 0xff] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
function chunk(type, data) {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const td = Buffer.concat([Buffer.from(type), data]);
  const c = Buffer.alloc(4); c.writeUInt32BE(crc(td));
  return Buffer.concat([len, td, c]);
}
function encode(S, px) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(S, 0); ihdr.writeUInt32BE(S, 4); ihdr[8] = 8; ihdr[9] = 6;
  const raw = Buffer.alloc(S * (S * 4 + 1));
  for (let y = 0; y < S; y++) px.copy(raw, y * (S * 4 + 1) + 1, y * S * 4, (y + 1) * S * 4);
  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk('IHDR', ihdr), chunk('IDAT', zlib.deflateSync(raw)), chunk('IEND', Buffer.alloc(0)),
  ]);
}

module.exports = { draw };

if (require.main === module) {
  const root = path.join(__dirname, '..');
  const out = (rel, buf) => { const f = path.join(root, rel); fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, buf); console.log('wrote', rel); };
  out('apps/desktop/electron/icon.png', draw(256));
  out('packages/core/icons/icon-192.png', draw(192));
  out('packages/core/icons/icon-512.png', draw(512));
  out('packages/core/icons/maskable-512.png', draw(512, { bleed: true, markScale: 0.72 }));
  out('packages/core/icons/apple-touch-icon.png', draw(180, { bleed: true, markScale: 0.85 }));
  out('apps/website/assets/icon-64.png', draw(64));
  out('apps/website/assets/icon-192.png', draw(192));
}
